    "ce": "# Rows that grow — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 RowsThatGrow.py RowsThatGrow\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass RowsThatGrow(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # rows: x + 3 &= 5 \\\\ x &= 5 - 3 \\\\ x &= 2\n        rows = MathTex(r\"\"\"x + 3 &= 5 \\\\\n  x &= 5 - 3 \\\\\n  x &= 2\"\"\", font_size=96)\n        rows_g = _glyphs(rows, [\n            (-0.8064, 0.3625, 0.1486, 0.1382), (-0.5304, 0.3732, 0.2032, 0.2029), (-0.2677, 0.3949, 0.1266, 0.2096), (0.0122, 0.3731, 0.2032, 0.0714),\n            (0.2918, 0.395, 0.1218, 0.2099), (-0.2808, -0.0342, 0.1486, 0.1382), (0.0122, -0.0236, 0.2032, 0.0714), (0.2918, -0.0017, 0.1218, 0.2099),\n            (0.5548, -0.0236, 0.1861, 0.0122), (0.8174, -0.0018, 0.1266, 0.2096), (-0.2808, -0.4309, 0.1486, 0.1382), (0.0122, -0.4204, 0.2032, 0.0714),\n            (0.2918, -0.395, 0.1218, 0.2032),\n        ])\n        VGroup(rows_g[1], rows_g[2], rows_g[8], rows_g[9]).set_color(\"#F4C867\")\n        rows_g[12].set_color(\"#5CD0B3\")\n\n        # 0 s – 1 s: rows fade_in\n        self.play(FadeIn(VGroup(*rows_g[:5])), run_time=1)\n        # 1 s – 2 s\n        self.wait(1)\n        # 2 s – 3 s: rows morph\n        self.play(\n            ReplacementTransform(rows_g[0].copy(), rows_g[5]),\n            ReplacementTransform(rows_g[3].copy(), rows_g[6]),\n            ReplacementTransform(rows_g[4].copy(), rows_g[7]),\n            ReplacementTransform(rows_g[1].copy(), rows_g[8]),\n            ReplacementTransform(rows_g[2].copy(), rows_g[9]),\n            run_time=1,\n        )\n        # 3 s – 4.4 s\n        self.wait(1.4)\n        # 4.4 s – 5.4 s: rows morph\n        self.play(\n            ReplacementTransform(rows_g[5].copy(), rows_g[10]),\n            ReplacementTransform(rows_g[6].copy(), rows_g[11]),\n            run_time=1,\n        )\n        # 5.4 s – 5.6 s\n        self.wait(0.2)\n        # 5.6 s – 6.4 s: rows write\n        self.play(Write(rows_g[12]), run_time=0.8)\n        # 6.4 s – 8.2 s\n        self.wait(1.8)\n        # 8.2 s – 9 s: rows fade_out\n        self.play(FadeOut(rows), run_time=0.8)\n",
    "gl": "# Rows that grow — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl RowsThatGrow.py RowsThatGrow -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 540 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass RowsThatGrow(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # rows: x + 3 &= 5 \\\\ x &= 5 - 3 \\\\ x &= 2\n        rows = Tex(r\"\"\"x + 3 &= 5 \\\\\n  x &= 5 - 3 \\\\\n  x &= 2\"\"\", font_size=98.9888)\n        rows_g = _glyphs(rows, [\n            (-0.8064, 0.3625, 0.1486, 0.1382), (-0.5304, 0.3732, 0.2032, 0.2029), (-0.2677, 0.3949, 0.1266, 0.2096), (0.0122, 0.3731, 0.2032, 0.0714),\n            (0.2918, 0.395, 0.1218, 0.2099), (-0.2808, -0.0342, 0.1486, 0.1382), (0.0122, -0.0236, 0.2032, 0.0714), (0.2918, -0.0017, 0.1218, 0.2099),\n            (0.5548, -0.0236, 0.1861, 0.0122), (0.8174, -0.0018, 0.1266, 0.2096), (-0.2808, -0.4309, 0.1486, 0.1382), (0.0122, -0.4204, 0.2032, 0.0714),\n            (0.2918, -0.395, 0.1218, 0.2032),\n        ])\n        VGroup(rows_g[1], rows_g[2], rows_g[8], rows_g[9]).set_color(\"#F4C867\")\n        rows_g[12].set_color(\"#5CD0B3\")\n\n        # 0 s – 1 s: rows fade_in\n        self.play(FadeIn(VGroup(*rows_g[:5])), run_time=1)\n        # 1 s – 2 s\n        self.wait(1)\n        # 2 s – 3 s: rows morph\n        self.play(\n            TransformFromCopy(rows_g[0], rows_g[5]),\n            TransformFromCopy(rows_g[3], rows_g[6]),\n            TransformFromCopy(rows_g[4], rows_g[7]),\n            TransformFromCopy(rows_g[1], rows_g[8]),\n            TransformFromCopy(rows_g[2], rows_g[9]),\n            run_time=1,\n        )\n        # 3 s – 4.4 s\n        self.wait(1.4)\n        # 4.4 s – 5.4 s: rows morph\n        self.play(\n            TransformFromCopy(rows_g[5], rows_g[10]),\n            TransformFromCopy(rows_g[6], rows_g[11]),\n            run_time=1,\n        )\n        # 5.4 s – 5.6 s\n        self.wait(0.2)\n        # 5.6 s – 6.4 s: rows write\n        self.play(Write(VGroup(rows_g[12]), stroke_color=\"#FFFFFF\"), run_time=0.8)\n        # 6.4 s – 8.2 s\n        self.wait(1.8)\n        # 8.2 s – 9 s: rows fade_out\n        self.play(FadeOut(rows), run_time=0.8)\n"
